const sourceDbTimeFields=['created_at','received_at','completed_at','authorized_at','recorded_at'];
function sourceOffset9(value:string){const fraction=/\.([0-9]+)Z$/.exec(value)?.[1]??'000',date=new Date(value);date.setUTCHours(date.getUTCHours()+9);return date.toISOString().slice(0,19)+'.'+fraction+'+09:00';}
async function captureSourceReport(f:any){const old=Buffer.byteLength;let report:any;try{(Buffer as any).byteLength=(value:any,...args:any[])=>{const n=(old as any)(value,...args);if(typeof value==='string'&&value.includes('"kind":"SOURCE_ROOT_HISTORY_INVENTORY_V1"')){const parsed=JSON.parse(value);if(parsed.kind==='SOURCE_ROOT_HISTORY_INVENTORY_V1')report=parsed;}return n;};const root=await historyRun(f);assert(report);return{root,report};}finally{Buffer.byteLength=old;}}
