test('source root history profile normalized metadata originalHash and audit derivedH ignore encoding but retain microseconds',async()=>inventoryFixture(async f=>{await produceRoots(f);microSourceEvents(f);const originalResults=f.ledger.commands.map((c:any)=>H(c.result_ref)),originalRefs=f.rootTables.source_root_versions.map((v:any)=>v.content_hash);const first=await captureSourceReport(f);let changed=0;f.state.sourceEnvelopeHook=(_phase:string,_raw:string,row:any)=>{for(const key of sourceDbTimeFields)if(typeof row[key]==='string'){row[key]=sourceOffset9(row[key]);changed++;}};const second=await captureSourceReport(f);assert(changed>0);assert.equal(first.root.components.find((c:any)=>c.name==='SourceRootHistory').originalHash,second.root.components.find((c:any)=>c.name==='SourceRootHistory').originalHash);const one=first.report.evidence.flatMap((e:any)=>e.audits),two=second.report.evidence.flatMap((e:any)=>e.audits);assert.deepEqual(one,two);for(const audit of one){const raw=f.ledger.audit_events.find((e:any)=>e.event_id===audit.eventId);assert.equal(audit.derivedMetadataHash,H({...raw,server_sequence:String(raw.server_sequence),recorded_at:'2026-10-18T00:00:00.123456Z'}));}assert(first.report.versions.every((v:any)=>v.createdAt==='2026-10-18T00:00:00.123456Z'));assert.deepEqual(f.ledger.commands.map((c:any)=>H(c.result_ref)),originalResults);assert.deepEqual(f.rootTables.source_root_versions.map((v:any)=>v.content_hash),originalRefs);}));
